func (q *Queries) ListMemberIntegrationGrants(ctx context.Context, arg ListMemberIntegrationGrantsParams) ([]IntegrationMemberGrant, error) {
	rows, err := q.db.Query(ctx, listMemberIntegrationGrants, arg.WorkspaceID, arg.MemberID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []IntegrationMemberGrant
	for rows.Next() {
		var i IntegrationMemberGrant
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.IntegrationInstallationID,
			&i.MemberID,
			&i.ExternalUserID,
			&i.Scopes,
			&i.CredentialsEncrypted,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RevokedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

